<script lang="ts">
  import { createProductionAutomation, type Pattern, type ProductionAutomation, type ProductionGradeRule, type ProductionBodyMapping, type ProductionMarkerSettings } from '@seamer/pattern-model';
  import { approveProductionDocument, productionApprovalState, resolveProductionTarget, materialMarkerPattern, consumptionFingerprint, markerConsumptionFromLayout, resolveProductionConsumption } from '$lib/utils/productionAutomation';
  import { nestInWorker } from '$lib/utils/nestingClient';
  import { markerToSVG } from '$lib/utils/markerLayout';
  import { downloadText } from '@atelier/io/browser';
  import { toastError } from '$lib/stores/toast';
  import { convertSpecValue } from '$lib/utils/productionSpec';
  import { productionGeometryFingerprint } from '$lib/utils/productionAutomation';
  import { measureProductionSurface, type ProductionSurfaceMesh } from '$lib/utils/surfaceMeasurement';
  import type { ProductionSurfaceMeasurement } from '@seamer/pattern-model';
  interface Props { readOnly?: boolean; pattern: Pattern; onchange: (pattern: Pattern, label?: string) => void; }
  let { pattern, onchange, readOnly = false }: Props = $props();
  const doc = $derived(pattern.productionAutomation ?? createProductionAutomation());
  const sizes = $derived(pattern.techPack?.sizes ?? []);
  const poms = $derived(pattern.productionSpec?.measurements ?? []);
  const assigned = $derived(pattern.materials.filter(material => pattern.pieces.some(piece => piece.materialId === material.id)));
  const approval = $derived(productionApprovalState(pattern));
  let approver = $state('');
  let approvalNotes = $state('');
  let calculating = $state<string | null>(null);
  let cancelCalculation: (() => void) | undefined;
  let capturingSurface = $state(false);
  $effect(() => () => cancelCalculation?.());
  function save(next: ProductionAutomation, label: string) { if (readOnly) return; onchange({ ...($state.snapshot(pattern) as Pattern), productionAutomation: $state.snapshot(next), hasChanged: true }, label); }
  const number = (value: string) => value.trim() && Number.isFinite(Number(value)) ? Number(value) : null;
  const positiveNumber = (value: string) => { const parsed = number(value); return parsed !== null && parsed >= 0 ? parsed : null; };
  function grade(pomId: string): ProductionGradeRule { const row = poms.find(row => row.id === pomId)!; return doc.grades.find(rule => rule.pomId === pomId) ?? { pomId, baseSizeId: pattern.techPack?.sampleSizeId ?? sizes[0]?.id ?? '', baseTarget: row.target, increment: 0, unit: row.unit, source: 'entered' }; }
  function setGrade(pomId: string, patch: Partial<ProductionGradeRule>) { const next = { ...grade(pomId), ...patch }; save({ ...doc, grades: [...doc.grades.filter(rule => rule.pomId !== pomId), next] }, 'Edit production grade rule'); }
  function mapping(pomId: string): ProductionBodyMapping { return doc.bodyMappings.find(mapping => mapping.pomId === pomId) ?? { pomId, bodyRowId: doc.bodyChart[0]?.id ?? '', factor: 1, ease: 0, unit: 'mm' }; }
  function setMapping(pomId: string, patch: Partial<ProductionBodyMapping>) {
    const prior = mapping(pomId);
    const next = { ...prior, ...patch, ease: patch.unit && patch.unit !== prior.unit ? convertSpecValue(prior.ease, prior.unit, patch.unit) ?? 0 : patch.ease ?? prior.ease };
    save({ ...doc, bodyMappings: [...doc.bodyMappings.filter(row => row.pomId !== pomId), next] }, 'Edit body garment mapping');
  }
  function settings(materialId: string): ProductionMarkerSettings { return doc.markerSettings.find(row => row.materialId === materialId) ?? { materialId, fabricWidthMm: 1400, gapMm: 10, allowHalfTurn: false, wastePercent: 0 }; }
  function setSettings(materialId: string, patch: Partial<ProductionMarkerSettings>) {
    const next = { ...settings(materialId), ...patch };
    next.fabricWidthMm = Math.max(1, next.fabricWidthMm); next.gapMm = Math.max(0, next.gapMm); next.wastePercent = Math.max(0, Math.min(1000, next.wastePercent));
    save({ ...doc, markerSettings: [...doc.markerSettings.filter(row => row.materialId !== materialId), next] }, 'Edit production marker settings');
  }
  async function calculate(materialId: string) {
    if (readOnly || calculating) return;
    const snapshot = $state.snapshot(pattern) as Pattern;
    const configured = settings(materialId);
    const fingerprint = consumptionFingerprint(snapshot, configured);
    calculating = materialId;
    try {
      const job = nestInWorker(materialMarkerPattern(snapshot, materialId), { fabricWidthMm: configured.fabricWidthMm, gapMm: configured.gapMm, allowedRotations: configured.allowHalfTurn ? [0, 180] : [0], generations: 4, population: 8, seed: 17 });
      cancelCalculation = job.cancel;
      const layout = await job.promise;
      if (consumptionFingerprint(pattern, settings(materialId)) !== fingerprint) throw new Error('Fabric geometry or marker settings changed during calculation. Calculate again.');
      const result = markerConsumptionFromLayout(snapshot, configured, layout);
      save({ ...doc, markerSettings: [...doc.markerSettings.filter(row => row.materialId !== materialId), configured], consumption: [...doc.consumption.filter(row => row.materialId !== materialId), result] }, 'Calculate fabric consumption');
    } catch (error) { toastError(error instanceof Error ? error.message : 'Could not calculate the fabric marker.'); }
    finally { cancelCalculation = undefined; calculating = null; }
  }
  function downloadMarker(materialId: string) {
    const { record, quantity } = resolveProductionConsumption(pattern, materialId);
    if (!record || quantity === null) return;
    downloadText('production-marker.svg', markerToSVG({ fabricWidthMm: record.settings.fabricWidthMm, usedLengthMm: record.usedLengthMm, gapMm: record.settings.gapMm, placements: record.placements.map(row => ({ pieceId: row.pieceId, instanceId: row.instanceId, name: pattern.pieces.find(piece => piece.id === row.pieceId)?.name ?? row.pieceId, poly: row.polygon, outline: row.polygon, bbox: { w: 0, h: 0 }, rotationDeg: row.rotationDeg })) }), 'image/svg+xml');
  }
  function updateSurface(id: string, patch: Partial<ProductionSurfaceMeasurement>) {
    if (readOnly) return;
    const changesGeometry = 'from' in patch || 'to' in patch || 'pieceId' in patch || 'method' in patch;
    const productionAutomation = { ...doc, surfaceMeasurements: doc.surfaceMeasurements.map(row => row.id === id ? { ...row, ...patch, captured: changesGeometry ? undefined : row.captured } : row) };
    if ('pomId' in patch && pattern.productionSpec) {
      onchange({ ...($state.snapshot(pattern) as Pattern), productionAutomation, productionSpec: { ...pattern.productionSpec, measurements: pattern.productionSpec.measurements.map(row => row.id === patch.pomId ? { ...row, annotationId: null, surfaceMeasurementId: id, manualValue: null } : row.surfaceMeasurementId === id ? { ...row, surfaceMeasurementId: null } : row) }, hasChanged: true }, 'Link surface measurement to POM');
    } else save(productionAutomation, 'Edit surface measurement');
  }
  async function captureSurface(id: string) {
    if (readOnly || capturingSurface) return;
    const row = doc.surfaceMeasurements.find(row => row.id === id); if (!row) return;
    const fingerprint = productionGeometryFingerprint(pattern);
    capturingSurface = true;
    try {
      const meshes = await new Promise<ProductionSurfaceMesh[]>((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error('Open a ready 3D pane to capture the current cloth mesh.')), 1500);
        window.dispatchEvent(new CustomEvent('seamer:capture-surface', { detail: { respond: (meshes: ProductionSurfaceMesh[]) => { clearTimeout(timeout); resolve(meshes); }, reject: (message: string) => { clearTimeout(timeout); reject(new Error(message)); } } }));
      });
      if (fingerprint !== productionGeometryFingerprint(pattern)) throw new Error('The document changed during mesh capture. Capture again.');
      const mesh = meshes.find(mesh => mesh.pieceId === row.pieceId);
      if (!mesh) throw new Error('The selected piece has no current rendered cloth mesh.');
      const valueMm = measureProductionSurface(mesh, row.from, row.to, row.method);
      save({ ...doc, surfaceMeasurements: doc.surfaceMeasurements.map(item => item.id === id ? { ...item, captured: { valueMm, source: `Current rendered cloth · first cut instance · ${row.method === 'chord' ? '3D chord' : 'mesh-edge surface path'}`, capturedAt: new Date().toISOString(), geometryFingerprint: fingerprint } } : item) }, 'Capture garment surface measurement');
    } catch (error) { toastError(error instanceof Error ? error.message : 'Could not measure the current cloth mesh.'); }
    finally { capturingSurface = false; }
  }
</script>

<div data-testid="production-automation-panel" class="space-y-6">
  <section><h3 class="font-semibold mb-2">Automatic production targets</h3><p class="text-xs opacity-60 mb-3">The ordered production sizes define grade steps. Manual size targets override a body mapping or grade rule; sample actuals stay independently measured.</p>
    {#if !sizes.length || !poms.length}<p class="text-sm">Add POMs and production sizes in Tech Pack to configure automatic targets.</p>{/if}
    {#each poms as pom (pom.id)}{@const rule = grade(pom.id)}{@const map = mapping(pom.id)}<article class="border border-base-300 rounded-lg p-3 mb-3" data-testid="production-grade-row"><h4 class="font-semibold text-sm mb-2">{pom.name}</h4>
      <label class="field mb-2">Target source<select disabled={readOnly} class="select select-bordered select-sm" aria-label={`${pom.name} automatic target source`} value={doc.bodyMappings.some(row => row.pomId === pom.id) ? 'body' : doc.grades.some(row => row.pomId === pom.id) ? 'grade' : 'none'} onchange={e => { if (e.currentTarget.value === 'grade') { save({ ...doc, bodyMappings: doc.bodyMappings.filter(row => row.pomId !== pom.id), grades: [...doc.grades.filter(row => row.pomId !== pom.id), rule] }, 'Enable production grading'); } else if (e.currentTarget.value === 'body') { save({ ...doc, grades: doc.grades.filter(row => row.pomId !== pom.id), bodyMappings: [...doc.bodyMappings.filter(row => row.pomId !== pom.id), map] }, 'Enable body chart mapping'); } else save({ ...doc, grades: doc.grades.filter(row => row.pomId !== pom.id), bodyMappings: doc.bodyMappings.filter(row => row.pomId !== pom.id) }, 'Disable automatic target'); }}><option value="none">Manual values only</option><option value="grade" disabled={!sizes.length}>Grade increment</option><option value="body" disabled={!doc.bodyChart.length || pom.unit === 'deg'}>Body chart and ease</option></select></label>
      {#if doc.grades.some(row => row.pomId === pom.id)}<div class="flex flex-wrap gap-3"><label class="field">Base size<select disabled={readOnly} class="select select-bordered select-sm" aria-label={`${pom.name} grade base size`} value={rule.baseSizeId} onchange={e => setGrade(pom.id, { baseSizeId: e.currentTarget.value })}>{#if !sizes.some(size => size.id === rule.baseSizeId)}<option value={rule.baseSizeId}>Missing size</option>{/if}{#each sizes as size (size.id)}<option value={size.id}>{size.name}</option>{/each}</select></label><label class="field">Base source<select disabled={readOnly} class="select select-bordered select-sm" aria-label={`${pom.name} grade base source`} value={rule.source} onchange={e => setGrade(pom.id, { source: e.currentTarget.value as ProductionGradeRule['source'] })}><option value="entered">Entered base target</option><option value="sample-target">Live POM target</option></select></label><label class="field">Base target ({rule.unit})<input class="input input-bordered input-sm w-28" type="number" min="0" step="any" disabled={readOnly || rule.source === 'sample-target'} aria-label={`${pom.name} grade base target`} value={rule.baseTarget ?? ''} onchange={e => setGrade(pom.id, { baseTarget: positiveNumber(e.currentTarget.value) })} /></label><label class="field">Increment per size ({rule.unit})<input disabled={readOnly} class="input input-bordered input-sm w-28" type="number" step="any" aria-label={`${pom.name} grade increment`} value={rule.increment} onchange={e => setGrade(pom.id, { increment: number(e.currentTarget.value) ?? 0 })} /></label></div>{/if}
      {#if doc.bodyMappings.some(row => row.pomId === pom.id)}<div class="flex flex-wrap gap-3"><label class="field">Body measurement<select disabled={readOnly} class="select select-bordered select-sm" aria-label={`${pom.name} body measurement`} value={map.bodyRowId} onchange={e => setMapping(pom.id, { bodyRowId: e.currentTarget.value })}>{#if !doc.bodyChart.some(row => row.id === map.bodyRowId)}<option value={map.bodyRowId}>Missing body row</option>{/if}{#each doc.bodyChart as row (row.id)}<option value={row.id}>{row.name}</option>{/each}</select></label><label class="field">Body multiplier<input disabled={readOnly} class="input input-bordered input-sm w-28" type="number" min="0.0001" step="any" aria-label={`${pom.name} body multiplier`} value={map.factor} onchange={e => setMapping(pom.id, { factor: Math.max(0.0001, number(e.currentTarget.value) ?? 1) })} /></label><label class="field">Garment ease ({map.unit})<input disabled={readOnly} class="input input-bordered input-sm w-28" type="number" step="any" aria-label={`${pom.name} garment ease`} value={map.ease} onchange={e => setMapping(pom.id, { ease: number(e.currentTarget.value) ?? 0 })} /></label><label class="field">Ease unit<select disabled={readOnly} class="select select-bordered select-sm" aria-label={`${pom.name} ease unit`} value={map.unit} onchange={e => setMapping(pom.id, { unit: e.currentTarget.value as ProductionBodyMapping['unit'] })}><option>mm</option><option>cm</option><option>inch</option></select></label></div>{/if}
      <div class="flex flex-wrap gap-3 mt-3">{#each sizes as size (size.id)}{@const target = resolveProductionTarget(pattern, pom.id, size.id)}<output class="text-xs" class:text-error={!target.valid} data-testid="production-target">{size.name}: {target.target === null ? '—' : Number(target.target.toFixed(4))} {pom.unit} · {target.source}</output>{/each}</div>
    </article>{/each}
    {#each doc.grades.filter(rule => !poms.some(pom => pom.id === rule.pomId)) as rule}<p class="text-error text-xs">Missing POM for grade rule {rule.pomId}. <button disabled={readOnly} class="btn btn-xs" onclick={() => save({ ...doc, grades: doc.grades.filter(row => row !== rule) }, 'Remove obsolete grade rule')}>Remove rule</button></p>{/each}
  </section>
  <section><div class="flex justify-between gap-2 mb-3"><h3 class="font-semibold">Body size chart</h3><button disabled={readOnly} class="btn btn-sm" onclick={() => save({ ...doc, bodyChart: [...doc.bodyChart, { id: crypto.randomUUID(), name: 'Body measurement', unit: 'cm', values: {} }] }, 'Add body chart row')}>Add body chart row</button></div><p class="text-xs opacity-60 mb-3">Body values describe the wearer. Garment targets use a separately authored multiplier and ease.</p>
    {#each doc.bodyChart as row (row.id)}<article class="border border-base-300 rounded-lg p-3 mb-3"><div class="flex flex-wrap gap-2 mb-3"><input disabled={readOnly} class="input input-bordered input-sm" aria-label="Body chart name" value={row.name} onchange={e => save({ ...doc, bodyChart: doc.bodyChart.map(item => item.id === row.id ? { ...item, name: e.currentTarget.value } : item) }, 'Rename body measurement')} /><select disabled={readOnly} class="select select-bordered select-sm" aria-label="Body chart unit" value={row.unit} onchange={e => { const unit = e.currentTarget.value as typeof row.unit; save({ ...doc, bodyChart: doc.bodyChart.map(item => item.id === row.id ? { ...item, unit, values: Object.fromEntries(Object.entries(item.values).map(([key, value]) => [key, convertSpecValue(value, item.unit, unit)])) } : item) }, 'Convert body chart unit'); }}><option>mm</option><option>cm</option><option>inch</option></select><button disabled={readOnly} class="btn btn-sm" aria-label={`Delete body chart ${row.name}`} onclick={() => save({ ...doc, bodyChart: doc.bodyChart.filter(item => item.id !== row.id) }, 'Delete body chart row')}>Delete</button></div><div class="flex flex-wrap gap-3">{#each sizes as size (size.id)}<label class="field">{size.name}<input disabled={readOnly} class="input input-bordered input-sm w-28" type="number" min="0" step="any" aria-label={`${row.name} ${size.name} body value`} value={row.values[size.id] ?? ''} onchange={e => save({ ...doc, bodyChart: doc.bodyChart.map(item => item.id === row.id ? { ...item, values: { ...item.values, [size.id]: positiveNumber(e.currentTarget.value) } } : item) }, 'Edit body chart value')} /></label>{/each}</div></article>{/each}
  </section>
  <section><h3 class="font-semibold mb-2">Fabric consumption from cutting markers</h3><p class="text-xs opacity-60 mb-3">True-shape nesting includes every cut copy and seam allowance for one garment. Width, drafted grain direction, end-for-end permission, spacing and purchase waste are explicit. Recalculate after piece or setting edits. Pattern matching, shrinkage and production yield need their own allowances.</p>
    {#each assigned as material (material.id)}{@const configured = settings(material.id)}{@const result = resolveProductionConsumption(pattern, material.id)}<article class="border border-base-300 rounded-lg p-3 mb-3" data-testid="production-marker-row"><h4 class="font-semibold text-sm mb-3">{material.name}</h4><div class="flex flex-wrap gap-3"><label class="field">Usable fabric width (mm)<input disabled={readOnly} class="input input-bordered input-sm w-28" type="number" min="1" aria-label={`${material.name} marker width`} value={configured.fabricWidthMm} onchange={e => setSettings(material.id, { fabricWidthMm: number(e.currentTarget.value) ?? 1400 })} /></label><label class="field">Piece spacing (mm)<input disabled={readOnly} class="input input-bordered input-sm w-28" type="number" min="0" aria-label={`${material.name} marker gap`} value={configured.gapMm} onchange={e => setSettings(material.id, { gapMm: number(e.currentTarget.value) ?? 10 })} /></label><label class="field">Purchase waste (%)<input disabled={readOnly} class="input input-bordered input-sm w-28" type="number" min="0" max="1000" aria-label={`${material.name} marker waste`} value={configured.wastePercent} onchange={e => setSettings(material.id, { wastePercent: number(e.currentTarget.value) ?? 0 })} /></label><label class="text-xs flex gap-2 items-center"><input disabled={readOnly} type="checkbox" class="checkbox checkbox-sm" aria-label={`${material.name} allow half turn`} checked={configured.allowHalfTurn} onchange={e => setSettings(material.id, { allowHalfTurn: e.currentTarget.checked })} />Allow 180° turns</label></div><div class="flex flex-wrap gap-2 items-center mt-3"><button class="btn btn-sm btn-primary" disabled={readOnly || calculating !== null} onclick={() => calculate(material.id)}>Calculate {material.name} consumption</button>{#if calculating === material.id}<button disabled={readOnly} class="btn btn-sm" onclick={() => cancelCalculation?.()}>Cancel calculation</button>{/if}<button class="btn btn-sm" disabled={result.quantity === null} onclick={() => downloadMarker(material.id)}>Download {material.name} marker</button><output class="text-xs" data-testid="production-consumption">{result.quantity === null ? '—' : Number(result.quantity.toFixed(4))} m · {result.status}</output></div>{#if result.record}<p class="text-xs opacity-60 mt-2">{result.record.cutCopies} cut copies · marker {Number((result.record.usedLengthMm / 1000).toFixed(4))} m · {result.record.calculatedAt}</p>{/if}</article>{/each}
  </section>
  <section><div class="flex justify-between gap-2 mb-3"><h3 class="font-semibold">Current 3D cloth measurements</h3><button class="btn btn-sm" disabled={readOnly || !pattern.pieces.length} onclick={() => save({ ...doc, surfaceMeasurements: [...doc.surfaceMeasurements, { id: crypto.randomUUID(), name: 'Surface measurement', pomId: null, pieceId: pattern.pieces[0].id, from: { x: 0, y: 0 }, to: { x: 100, y: 0 }, method: 'surface-path' }] }, 'Add surface measurement')}>Add surface measurement</button></div><p class="text-xs opacity-60 mb-3">Endpoints use piece UV draft coordinates in millimeters. Capture a straight 3D chord or a shortest mesh-edge surface path from an open 3D pane. The surface path approximates a geodesic at the current tessellation; disconnected or outside endpoints fail explicitly. Captures are snapshots: capture again after runtime simulation moves the cloth.</p>
    {#each doc.surfaceMeasurements as row (row.id)}<article class="border border-base-300 rounded-lg p-3 mb-3" data-testid="production-surface-row"><div class="flex flex-wrap gap-3"><label class="field">Measurement name<input disabled={readOnly} class="input input-bordered input-sm" aria-label="Surface measurement name" value={row.name} onchange={e => updateSurface(row.id, { name: e.currentTarget.value })} /></label><label class="field">Piece<select disabled={readOnly} class="select select-bordered select-sm" aria-label="Surface measurement piece" value={row.pieceId} onchange={e => updateSurface(row.id, { pieceId: e.currentTarget.value })}>{#if !pattern.pieces.some(piece => piece.id === row.pieceId)}<option value={row.pieceId}>Missing piece</option>{/if}{#each pattern.pieces as piece (piece.id)}<option value={piece.id}>{piece.name}</option>{/each}</select></label><label class="field">Method<select disabled={readOnly} class="select select-bordered select-sm" aria-label="Surface measurement method" value={row.method} onchange={e => updateSurface(row.id, { method: e.currentTarget.value as typeof row.method })}><option value="surface-path">Mesh-edge surface path</option><option value="chord">3D straight chord</option></select></label><label class="field">Link POM<select disabled={readOnly} class="select select-bordered select-sm" aria-label="Surface measurement POM" value={row.pomId ?? ''} onchange={e => updateSurface(row.id, { pomId: e.currentTarget.value || null })}><option value="">Unlinked</option>{#if row.pomId && !poms.some(pom => pom.id === row.pomId)}<option value={row.pomId}>Missing POM</option>{/if}{#each poms.filter(pom => pom.unit !== 'deg') as pom (pom.id)}<option value={pom.id}>{pom.name}</option>{/each}</select></label></div><div class="flex flex-wrap gap-3 mt-3">{#each ['from', 'to'] as endpoint}{#each ['x', 'y'] as axis}<label class="field">{endpoint} {axis} (mm)<input disabled={readOnly} class="input input-bordered input-sm w-24" type="number" step="any" aria-label={`Surface ${endpoint} ${axis}`} value={row[endpoint as 'from' | 'to'][axis as 'x' | 'y']} onchange={e => updateSurface(row.id, { [endpoint]: { ...row[endpoint as 'from' | 'to'], [axis]: number(e.currentTarget.value) ?? 0 } })} /></label>{/each}{/each}</div><div class="flex flex-wrap gap-2 items-center mt-3"><button class="btn btn-sm btn-primary" disabled={readOnly || capturingSurface} onclick={() => captureSurface(row.id)}>Capture {row.name}</button><button disabled={readOnly} class="btn btn-sm" onclick={() => save({ ...doc, surfaceMeasurements: doc.surfaceMeasurements.filter(item => item.id !== row.id) }, 'Delete surface measurement')}>Delete surface measurement</button><output class="text-xs" data-testid="production-surface-value">{row.captured ? `${Number(row.captured.valueMm.toFixed(4))} mm · ${row.captured.geometryFingerprint === productionGeometryFingerprint(pattern) ? 'Captured document geometry' : 'Stale geometry · capture again'}` : 'Not captured'}</output></div>{#if row.captured}<p class="text-xs opacity-60 mt-2">{row.captured.source} · {row.captured.capturedAt}</p>{/if}</article>{/each}
  </section>
  <section><h3 class="font-semibold mb-2">Production document approval</h3><output class="badge mb-3" class:badge-success={approval === 'approved'} class:badge-warning={approval === 'stale'} data-testid="production-approval">{approval === 'approved' ? 'Approved · current document' : approval === 'stale' ? 'Approval stale · review changes' : 'Awaiting document approval'}</output>{#if doc.approval}<p class="text-xs mb-3">{doc.approval.name} · {doc.approval.approvedAt} · {doc.approval.notes}</p>{/if}<div class="flex flex-wrap gap-3"><label class="field">Approver name<input disabled={readOnly} class="input input-bordered input-sm" aria-label="Production approver" bind:value={approver} /></label><label class="field">Review notes<input disabled={readOnly} class="input input-bordered input-sm" aria-label="Production approval notes" bind:value={approvalNotes} /></label><button class="btn btn-sm self-end" disabled={readOnly || !approver.trim()} onclick={() => save(approveProductionDocument(pattern, approver, approvalNotes), 'Approve production document')}>Approve current document</button>{#if doc.approval}<button disabled={readOnly} class="btn btn-sm self-end" onclick={() => save({ ...doc, approval: null }, 'Clear production approval')}>Clear approval</button>{/if}</div><p class="text-xs opacity-60 mt-3">This records your review of the authored document. Geometry, materials, artwork and production changes invalidate it; viewport/layout changes do not. It does not certify physical fit.</p></section>
</div>
<style>.field { display:flex;flex-direction:column;gap:.375rem;font-size:.75rem; }</style>
